; =====================================================================
;  music.asm : 1-bit music sequencer, ticked once per frame
;  Voice A (lead / arpeggio, pulse width via I), voice B (bass, square),
;  drums = 1-bit samples streamed by IX inside the line kernel.
;  Song data (song.inc) is generated by tools/song.py
; =====================================================================

m_tick:     db 1
m_row:      db 0
m_order:    dw song_orders
m_lead:     dw 0            ; pointer into current lead pattern
m_bass:     dw 0
m_drum:     dw 0
m_instr:    dw instruments  ; pointer to current instrument
m_insA:     dw instruments
m_insB:     dw instruments
m_trans:    db 0
m_lnote:    db 0            ; current lead note (0 = silent)
m_bnote:    db 0
m_bage:     db 0            ; frames since bass note on
m_lage:     db 0
m_arp:      db 0
m_duty:     db 0
m_dend:     dw silence      ; end of current drum sample
m_ix:       dw silence      ; drum pointer to hand to the kernel
m_fa:       dw 0
m_fb:       dw 0
m_patend:   db 0            ; set to 1 for one frame when a pattern (order) ends
m_mute:     db 0            ; bit0 lead muted, bit1 bass muted, bit2 drums muted
m_rowsper:  db 64
m_ordnum:   db 0
m_needload: db 0            ; index of the current order (pattern row of the song)

; call once to start the song from order 0
music_init:
        ld hl,song_orders
        ld (m_order),hl
        ld a,$FF
        ld (m_ordnum),a
        call m_load_order
        ld a,1
        ld (m_tick),a
        xor a
        ld (m_lnote),a
        ld (m_bnote),a
        ld (m_mute),a
        ld hl,silence
        ld (m_ix),hl
        ld (m_dend),hl
        ret

; load the order entry at (m_order)
m_load_order:
        ld hl,m_ordnum
        ld a,(hl)
        inc a
        cp 250
        jr nc,.nosat            ; saturate (the end screen loops forever)
        ld (hl),a
.nosat:
        ld hl,(m_order)
        ld a,(hl)
        cp $FF
        jr nz,.ok
        inc hl
        ld e,(hl)
        inc hl
        ld d,(hl)
        ex de,hl
        ld (m_order),hl
        ld a,(hl)
.ok:    ; entry: lead pat, bass pat, drum pat, instrA, instrB, transpose
        call .patptr
        ld (m_lead),de
        inc hl
        ld a,(hl)
        call .patptr
        ld (m_bass),de
        inc hl
        ld a,(hl)
        call .patptr
        ld (m_drum),de
        inc hl
        ld a,(hl)               ; instrument A
        call .insptr
        ld (m_insA),de
        ld (m_instr),de
        inc hl
        ld a,(hl)               ; instrument B (lead notes with bit 7 set)
        call .insptr
        ld (m_insB),de
        inc hl
        ld a,(hl)
        ld (m_trans),a
        inc hl
        ld (m_order),hl
        xor a
        ld (m_row),a
        ret
.insptr: push hl
        add a,a
        add a,a
        ld l,a
        ld h,0
        ld de,instruments
        add hl,de
        ex de,hl
        pop hl
        ret
.patptr: ; A = pattern number -> DE = pattern address
        push hl
        ld l,a
        ld h,0
        add hl,hl
        ld de,pat_ptrs
        add hl,de
        ld e,(hl)
        inc hl
        ld d,(hl)
        pop hl
        ret

; ---------------------------------------------------------------------
; music_tick: once per frame.  Leaves m_fa/m_fb/m_duty/m_ix ready;
; call music_apply right before entering the kernel.
; ---------------------------------------------------------------------
music_tick:
        xor a
        ld (m_patend),a
        ld hl,m_tick
        dec (hl)
        jr z,.row
        ld a,(m_needload)
        or a
        jp nz,.loadnow
        jp .frame
.row:
        ld (hl),SONG_SPEED
        ; ---- new row ----
        ld hl,(m_lead)
        ld a,(hl)
        inc hl
        ld (m_lead),hl
        or a
        jr z,.l_cont
        cp 1
        jr nz,.l_on
        xor a
        ld (m_lnote),a
        jr .l_cont
.l_on:  ld b,a
        ld hl,(m_insA)
        rla
        jr nc,.l_ia
        ld hl,(m_insB)
.l_ia:  ld (m_instr),hl
        ld a,b
        and $7F
        ld b,a
        ld a,(m_trans)
        add a,b
        ld (m_lnote),a
        xor a
        ld (m_lage),a
.l_cont:
        ld hl,(m_bass)
        ld a,(hl)
        inc hl
        ld (m_bass),hl
        or a
        jr z,.b_cont
        cp 1
        jr nz,.b_on
        xor a
        ld (m_bnote),a
        jr .b_cont
.b_on:  ld b,a
        ld a,(m_trans)
        add a,b
        ld (m_bnote),a
        xor a
        ld (m_bage),a
.b_cont:
        ld hl,(m_drum)
        ld a,(hl)
        inc hl
        ld (m_drum),hl
        or a
        jr z,.d_cont
        ld b,a
        ld a,(m_mute)
        and 4
        jr nz,.d_cont
        ld a,b
        dec a                   ; sample index
        add a,a
        add a,a
        ld l,a
        ld h,0
        ld de,drum_table
        add hl,de
        ld e,(hl)
        inc hl
        ld d,(hl)
        inc hl
        ld (m_ix),de
        ld e,(hl)
        inc hl
        ld d,(hl)
        ld (m_dend),de
.d_cont:
        ld hl,m_row
        inc (hl)
        ld a,(hl)
        cp 64
        jr nz,.frame2
        ld a,1
        ld (m_patend),a
        ld (m_needload),a       ; load the next order on the next (row-free) frame
.frame2:
        jr .frame
.loadnow:
        xor a
        ld (m_needload),a
        call m_load_order
        jr .frame
.frame: ; ---- per frame ----
        ; lead: arpeggio + pulse width table
        ld hl,m_lage
        inc (hl)
        ld a,(m_lnote)
        or a
        jr z,.lead_off
        ld b,a
        ld a,(m_arp)
        inc a
        cp 3
        jr c,.ar
        xor a
.ar:    ld (m_arp),a
        ld hl,(m_instr)         ; instrument: arp0 arp1 arp2 dutytable#
        ld e,a
        ld d,0
        add hl,de
        ld a,(hl)
        add a,b
        call note_freq
        ld (m_fa),hl
        ; duty
        ld hl,(m_instr)
        inc hl
        inc hl
        inc hl
        ld a,(hl)               ; duty table number (16 bytes each)
        add a,a
        add a,a
        add a,a
        add a,a
        ld e,a
        ld a,(m_lage)
        and 15
        or e
        ld e,a
        ld d,0
        ld hl,duty_tables
        add hl,de
        ld a,(hl)
        ld (m_duty),a
        jr .lead_done
.lead_off:
        ld hl,0
        ld (m_fa),hl
        xor a
        ld (m_duty),a
.lead_done:
        ld a,(m_mute)
        rrca
        jr nc,.lm
        ld hl,0
        ld (m_fa),hl
        xor a
        ld (m_duty),a
.lm:
        ; bass: pluck (one octave up for 2 frames)
        ld a,(m_bnote)
        or a
        jr z,.bass_off
        ld b,a
        ld hl,m_bage
        ld a,(hl)
        inc (hl)
        cp 2
        ld a,b
        jr nc,.bn
        add a,12
.bn:    call note_freq
        ld (m_fb),hl
        jr .bass_done
.bass_off:
        ld hl,0
        ld (m_fb),hl
.bass_done:
        ld a,(m_mute)
        and 2
        jr z,.bm
        ld hl,0
        ld (m_fb),hl
.bm:
        ret

; music_apply: load voice registers for the kernel. Call after any code
; that may have used IX or the alternate registers.
music_apply:
        ; a silent voice copies the other one so pulse-interleaving
        ; produces no 7.8kHz carrier
        ld hl,(m_fa)
        ld a,h
        or l
        jr nz,.fa_ok
        ld hl,(m_fb)
        ld (m_fa),hl
        ld a,$7F
        ld (m_duty),a
        exx
        push iy
        pop hl                  ; sync voice A phase to voice B
        exx
.fa_ok:
        ; drum: past end of sample -> silence
        ld hl,(m_ix)
        ld de,(m_dend)
        or a
        sbc hl,de
        jr c,.dok
        ld hl,silence
        ld (m_ix),hl
        ld (m_dend),hl
.dok:   ld a,(m_duty)
        ld i,a
        ld bc,(m_fb)
        ld de,(m_fa)
        exx
        ld bc,(m_fb)            ; -> BC'
        ld de,(m_fa)            ; -> DE'
        exx
        ld ix,(m_ix)
        ret

; after the kernel: save the advancing drum pointer
music_save:
        ld (m_ix),ix
        ret

; A = note (0..95) -> HL = frequency increment
note_freq:
        cp 96
        jr c,.ok
        ld a,95
.ok:    add a,a
        ld l,a
        ld h,0
        ld de,freq_table
        add hl,de
        ld a,(hl)
        inc hl
        ld h,(hl)
        ld l,a
        ret

silence:
        ds 256,0
